27	/** Approved providers for discovery, with optional filters. */
28	export async function listApprovedProviders(
29	  filters: BrowseFilters = {},
30	): Promise<PublicProvider[]> {
31	  const supabase = await createClient();
32	  let query = supabase
33	    .from("providers")
34	    .select(PUBLIC_PROVIDER_COLUMNS)
35	    .eq("status", "approved");
36	
37	  if (filters.topic) query = query.contains("topics", [filters.topic]);
38	  if (filters.language) query = query.contains("languages", [filters.language]);
39	  if (filters.availableNow) query = query.eq("is_available_now", true);
40	  if (typeof filters.maxPriceCents === "number") {
41	    query = query.lte("price_block_30_cents", filters.maxPriceCents);
42	  }
43	
44	  const { data, error } = await query.order("rating_avg", { ascending: false });
45	  if (error) throw error;
46	  return (data ?? []) as unknown as PublicProvider[];
47	}
