78	export interface AdminMetrics {
79	  strategic: AdminMetricsStrategic;
80	  operational: AdminMetricsOperational;
81	  alerts: AdminMetricsAlerts;
82	}
83	
84	/**
85	 * Read the precomputed admin metric views. Access to the views is revoked from
86	 * anon/authenticated, so this uses the service-role client — callers MUST guard
87	 * with requireRole("admin") first.
88	 */
89	export async function getAdminMetrics(): Promise<AdminMetrics> {
90	  const admin = createAdminClient();
91	  const [strategic, operational, alerts] = await Promise.all([
92	    admin.from("admin_metrics_strategic").select("*").single(),
93	    admin.from("admin_metrics_operational").select("*").single(),
94	    admin.from("admin_metrics_alerts").select("*").single(),
95	  ]);
96	  if (strategic.error) throw strategic.error;
97	  if (operational.error) throw operational.error;
98	  if (alerts.error) throw alerts.error;
99	  return {
100	    strategic: strategic.data,
101	    operational: operational.data,
102	    alerts: alerts.data,
103	  };
104	}
