106	/** Approved providers the customer has favorited (for the customer dashboard). */
107	export async function listFavoriteProviders(
108	  customerId: string,
109	): Promise<PublicProvider[]> {
110	  const supabase = await createClient();
111	  const { data: favs, error } = await supabase
112	    .from("favorites")
113	    .select("provider_id")
114	    .eq("customer_id", customerId);
115	  if (error) throw error;
116	  const ids = (favs ?? []).map((f) => f.provider_id);
117	  if (ids.length === 0) return [];
118	  const { data, error: pErr } = await supabase
119	    .from("providers")
120	    .select(PUBLIC_PROVIDER_COLUMNS)
121	    .in("id", ids)
122	    .eq("status", "approved");
123	  if (pErr) throw pErr;
124	  return (data ?? []) as unknown as PublicProvider[];
125	}
